const cfg = $('Set - Config').first().json;
const all = $input.first().json;

const order = all.order || all[0] || {};
const customer = all.customer || all[1] || {};
const inventory = all.inventory || all[2] || {};

return [{
  json: {
    ...cfg,
    orderId: cfg.body?.orderId,
    exceptionType: cfg.body?.exceptionType,
    fraudScoreFlagged: cfg.body?.fraudScoreFlagged || false,
    orderTotal: cfg.body?.orderTotal || order.total || 0,
    currency: cfg.body?.currency || order.currency || 'USD',
    orderDetails: order,
    customerProfile: customer,
    inventoryOptions: inventory
  }
}];

// The AI proposes; this code disposes. Every decision is re-validated
// against hard policy before it is allowed to execute anything.
const cfg = $('JS - Build Decision Context').first().json;
const response = $input.first().json;

const ALLOWED_ACTIONS = ['reissue_payment_link', 'substitute_sku', 'reroute_carrier', 'issue_store_credit', 'refund_order', 'escalate_to_human'];

const textBlock = (response.content || []).find(b => b.type === 'text');
let decision;
try {
  const raw = (textBlock?.text || '{}').replace(/```json|```/g, '').trim();
  decision = JSON.parse(raw);
} catch (e) {
  decision = { action: 'escalate_to_human', actionParams: { escalationReason: 'Failed to parse AI decision.' }, confidencePercent: 0, reasoning: 'Parse error - forced escalation.' };
}

let overridden = false;
let overrideReason = null;

if (!ALLOWED_ACTIONS.includes(decision.action)) {
  overridden = true;
  overrideReason = 'Disallowed or unknown action name: ' + decision.action;
  decision = { action: 'escalate_to_human', actionParams: { escalationReason: overrideReason }, confidencePercent: decision.confidencePercent || 0, reasoning: decision.reasoning || '' };
}

if (!overridden && cfg.fraudScoreFlagged === true) {
  overridden = true;
  overrideReason = 'Order is fraud-flagged; automated action blocked regardless of AI choice.';
  decision = { action: 'escalate_to_human', actionParams: { escalationReason: overrideReason }, confidencePercent: decision.confidencePercent, reasoning: decision.reasoning };
}

if (!overridden && cfg.orderTotal > cfg.requireHumanApprovalAboveAmount) {
  overridden = true;
  overrideReason = 'Order total ' + cfg.orderTotal + ' exceeds human-approval threshold ' + cfg.requireHumanApprovalAboveAmount + '.';
  decision = { action: 'escalate_to_human', actionParams: { escalationReason: overrideReason }, confidencePercent: decision.confidencePercent, reasoning: decision.reasoning };
}

if (!overridden && decision.action === 'refund_order') {
  const amt = Number(decision.actionParams?.amount || 0);
  if (amt > cfg.maxAutoRefundAmount) {
    overridden = true;
    overrideReason = 'Requested refund ' + amt + ' exceeds maxAutoRefundAmount ' + cfg.maxAutoRefundAmount + '.';
    decision = { action: 'escalate_to_human', actionParams: { escalationReason: overrideReason }, confidencePercent: decision.confidencePercent, reasoning: decision.reasoning };
  }
}

if (!overridden && decision.action === 'issue_store_credit') {
  const amt = Number(decision.actionParams?.amount || 0);
  if (amt > cfg.maxAutoCreditAmount) {
    overridden = true;
    overrideReason = 'Requested credit ' + amt + ' exceeds maxAutoCreditAmount ' + cfg.maxAutoCreditAmount + '.';
    decision = { action: 'escalate_to_human', actionParams: { escalationReason: overrideReason }, confidencePercent: decision.confidencePercent, reasoning: decision.reasoning };
  }
}

return [{
  json: {
    orderId: cfg.orderId,
    exceptionType: cfg.exceptionType,
    orderTotal: cfg.orderTotal,
    currency: cfg.currency,
    customerProfile: cfg.customerProfile,
    orderApiUrl: cfg.orderApiUrl,
    paymentApiUrl: cfg.paymentApiUrl,
    carrierApiUrl: cfg.carrierApiUrl,
    inventoryApiUrl: cfg.inventoryApiUrl,
    auditLogSheetId: cfg.auditLogSheetId,
    slackEscalationChannelId: cfg.slackEscalationChannelId,
    decidedAt: new Date().toISOString(),
    action: decision.action,
    actionParams: decision.actionParams || {},
    confidencePercent: decision.confidencePercent,
    reasoning: decision.reasoning,
    policyOverridden: overridden,
    policyOverrideReason: overrideReason
  }
}];

// Write the decision to the audit trail BEFORE execution, so the intended
// action is always on record even if execution later fails.
const d = $input.first().json;
return [{
  json: {
    ...d,
    auditStatus: 'decision_logged_pending_execution',
    auditLoggedAt: new Date().toISOString()
  }
}];

