// Whichever executor branch ran, its own item already carries the full
// decision record plus the raw API/Slack response merged in by n8n.
const result = $input.first().json;
const succeeded = !(result.error || result.errorMessage);

return [{
  json: {
    ...result,
    executionSucceeded: succeeded,
    executionResult: succeeded ? (result.body || result) : (result.error || result.errorMessage),
    executedAt: new Date().toISOString()
  }
}];

const d = $input.first().json;
return [{
  json: {
    ...d,
    auditStatus: d.executionSucceeded ? 'action_executed_successfully' : 'action_execution_failed',
    auditCompletedAt: new Date().toISOString()
  }
}];
